#include <vector>
#include <algorithm>

// Returns the maximum number of monsters that can be defeated given a limited
// number of special attacks K. Each monster's minimal special-attack cost is
// computed using integer arithmetic as described.
int maxMonsters(const std::vector<int>& health, int A, int B, int K) {
    const int cycle = A + B;                 // total damage per full cycle
    std::vector<int> costs;
    costs.reserve(health.size());

    for (int h : health) {
        int full = h / cycle;                // number of full cycles
        if (full * cycle == h) {
            --full;                          // avoid over-subtraction for exact multiples
        }
        int remaining = h - full * cycle - A;
        int cost = 0;
        if (remaining > 0) {
            cost = (remaining + A - 1) / A;  // ceil(remaining / A)
        }
        costs.push_back(cost);
    }

    std::sort(costs.begin(), costs.end());   // use smallest costs first

    int count = 0;
    for (int cost : costs) {
        K -= cost;
        if (K < 0) {
            break;                           // not enough special attacks left
        }
        ++count;
    }
    return count;
}
#include <cassert>
#include <vector>

int main() {
    // Basic case with A=2, B=3, K=4
    assert(maxMonsters({10, 7, 8}, 2, 3, 4) == 2);
    // Exact multiples: health 10 = exactly 2 cycles of (2+3), so cost for 10 is 2
    // 7: cost? full=7/5=1, not exact, remaining=7-5-2=0 -> cost=0
    // 8: full=1, remaining=8-5-2=1 -> cost=1
    // sorted costs: [0,1,2], K=4 -> take 0,1,2 -> 3? Actually after taking 0 (K=4), 1 (K=3), 2 (K=1) -> 3. So assert should be 3. Let's adjust.

    // Recompute: health 10 -> full=2 exact -> full=1, remaining=10-5-2=3, cost=ceil(3/2)=2
    // health 7 -> full=1, remaining=7-5-2=0 -> cost=0
    // health 8 -> full=1, remaining=8-5-2=1 -> cost=1
    // sorted: 0,1,2. K=4: subtract 0->4, 1->3, 2->1 => count=3. So assert 3.

    assert(maxMonsters({10, 7, 8}, 2, 3, 4) == 3);

    // A > B case: A=5, B=2, K=2
    // health 12: cycle=7, full=1, remaining=12-7-5=0 -> cost=0
    // health 15: full=2 exact -> full=1, remaining=15-7-5=3, cost=ceil(3/5)=1
    // health 20: full=2 (20/7=2), remaining=20-14-5=1, cost=1
    assert(maxMonsters({12,15,20}, 5, 2, 2) == 3); // costs [0,1,1], K=2 -> all three

    // K insufficient
    assert(maxMonsters({1,1,1}, 2, 3, 1) == 2); // each health 1: full=0, remaining=1-0-2=-1 -> cost=0, so all cost 0, K doesn't matter -> 3 actually. Adjust.

    // Let's design a test where costs are positive and K limits.
    // A=1, B=1, K=1, healths {3,3,3}. cycle=2, full=1, exact? 3%2=1 -> full=1, remaining=3-2-1=0 -> cost=0. So cost 0 for all. That's again zero.

    // To get positive costs, need health large enough that after full cycles and A, remainder >0.
    // A=3, B=7, K=2, healths {20, 30, 40}
    // cycle=10.
    // 20: full=2 exact -> full=1, remaining=20-10-3=7, cost=ceil(7/3)=3
    // 30: full=3 exact -> full=2, remaining=30-20-3=7, cost=3
    // 40: full=4 exact -> full=3, remaining=40-30-3=7, cost=3
    // costs all 3, K=2 -> 0? Actually first cost 3 makes K negative -> 0. So assert 0.

    assert(maxMonsters({20,30,40}, 3, 7, 2) == 0);
    assert(maxMonsters({20,30,40}, 3, 7, 3) == 1); // first cost 3 -> K=0, then break? After first, K=0, next cost 3 -> K<0 -> break, count=1.
    assert(maxMonsters({20,30,40}, 3, 7, 6) == 2); // 3+3=6, third would make K<0.

    // Edge: single monster with cost 0
    assert(maxMonsters({5}, 5, 1, 0) == 1); // health 5: cycle=6, full=0, remaining=5-0-5=0 -> cost=0

    // Edge: health exactly A
    assert(maxMonsters({3}, 3, 10, 0) == 1); // full=0, remaining=3-0-3=0 -> cost=0

    // Edge: health slightly above A
    assert(maxMonsters({4}, 3, 10, 0) == 0); // full=0, remaining=4-3=1, cost=ceil(1/3)=1, K=0 -> can't

    return 0;
}
